package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_compareTo_TriageGen3Test {







    @Test
    public void testCompareTo_NegativeValues() {
        // Testing negative logic
        Fraction f1 = new Fraction(-1, 2); // -0.5
        Fraction f2 = new Fraction(-1, 1); // -1.0
        // -0.5 > -1.0
        assertEquals(1, f1.compareTo(f2));

        Fraction f3 = new Fraction(-1, 1); // -1.0
        Fraction f4 = new Fraction(-1, 2); // -0.5
        // -1.0 < -0.5
        assertEquals(-1, f3.compareTo(f4));
    }




}

